import pandas as pd
def calculate_average_duration(listening_data):
    """Calculates and returns the average listening duration per genre for each user."""
    # Assuming listening_data is a dictionary of the form { "user_id": { "genre": duration, ... } }
    # We create a DataFrame from the listening_data dictionary
    df = pd.DataFrame.from_dict(listening_data, orient='index')
    # We calculate the average duration per user by grouping by user_id and taking the mean
    return df.groupby('user_id')['duration'].mean()


def identify_users_with_most_diverse_genres(listening_data, n=5):
    """Identifies users with the most diverse genre preferences and returns the top n users."""
    # Assuming listening_data is a dictionary of the form { "user_id": { "genre": duration, ... } }
    # We create a DataFrame from the listening_data dictionary
    df = pd.DataFrame.from_dict(listening_data, orient='index')
    # We calculate the number of unique genres per user by grouping by user_id and counting the number of unique values
    num_unique_genres = df.groupby('user_id')['genre'].nunique()
    # We sort the users by their number of unique genres in descending order
    sorted_users = num_unique_genres.sort_values(ascending=False).head(n).index
    # We return the top n users with the highest number of unique genres
    return sorted_users


